/// CBSA-WAGE-INDEX-RECORD
fn p_cbsa_wage_index_record(state: &mut ProgramState) {
    p_0200_mainline_control(state);
    return;
}

/// 0200-MAINLINE-CONTROL
fn p_0200_mainline_control(state: &mut ProgramState) {
    state.wk_hipps_code.hld_rate_rtc = Default::default();
    state.hold_variables.snfpr_version = FixedString::copy_from(&state.cal_version);
    state.ws_per_diem_subtotals.ws_pt_ot_util = Decimal::from(0i64);
    state.ws_per_diem_subtotals.ws_pt_ot_portion = Decimal::from(0i64);
    state.ws_per_diem_subtotals.ws_nta_util = Decimal::from(0i64);
    state.ws_per_diem_subtotals.ws_nta_portion = Decimal::from(0i64);
    state.ws_per_diem_subtotals.ws_nurs_slp_ncm_portion = Decimal::from(0i64);
    state.days_to_100 = 0;
    state.total_days = 0;
    state.tot_pdpm_casemix_perdiem = Decimal::from(0i64);
    state.total_calc_payment_rate = Decimal::from(0i64);
    state.labor_portion = Decimal::from(0i64);
    state.labor_adjusted = Decimal::from(0i64);
    state.non_labor_portion = Decimal::from(0i64);
    state.non_labor_adjusted = Decimal::from(0i64);
    state.total_labor_adj_rate = Decimal::from(0i64);
    state.sub2 = 1 as u32;
    if state.snf_data.snf_input_data.snf_pay_rtc.snf_rtc == 00 {
        p_300_default_hipps_check(state);
        p_300_exit(state);
        p_400_validate_snf_input(state);
        p_total_days(state);
        p_400_exit(state);
    }
}

