/// 700-CALC-UNADJUSTED-RATE
fn p_700_calc_unadjusted_rate(state: &mut ProgramState) {
    state.ws_per_diem_subtotals.ws_pt_ot_fee = Decimal::from(i64::from(state.hipps_per_diem_components.hipps_pt_rate_comp + state.hipps_per_diem_components.hipps_ot_rate_comp));
    state.ws_per_diem_subtotals.ws_pt_ot_portion = Decimal::from(i64::from(state.ws_per_diem_subtotals.ws_pt_ot_fee * state.ws_per_diem_subtotals.ws_pt_ot_util));
    state.ws_per_diem_subtotals.ws_nta_portion = Decimal::from(i64::from(state.hipps_per_diem_components.hipps_nta_rate_comp * state.ws_per_diem_subtotals.ws_nta_util));
    state.ws_per_diem_subtotals.ws_nurs_slp_ncm_portion = Decimal::from(i64::from((state.hipps_per_diem_components.hipps_nurse_rate_comp + state.hipps_per_diem_components.hipps_slp_rate_comp + state.hipps_per_diem_components.hipps_ncm_rate_comp) * state.current_days));
    state.tot_pdpm_casemix_perdiem = Decimal::from(i64::from((state.ws_per_diem_subtotals.ws_pt_ot_portion + state.ws_per_diem_subtotals.ws_nta_portion + state.ws_per_diem_subtotals.ws_nurs_slp_ncm_portion)));
    state.labor_portion = Decimal::from(i64::from((state.tot_pdpm_casemix_perdiem * state.labor_nlabor_percent.percent_2021_labor)));
    state.labor_adjusted = Decimal::from(i64::from((state.labor_portion * state.hold_variables.hold_var_data.area_wage_index)));
    state.non_labor_portion = Decimal::from(i64::from((state.tot_pdpm_casemix_perdiem * state.labor_nlabor_percent.percent_2021_nlabor)));
    state.total_labor_adj_rate = Decimal::from(i64::from((state.labor_adjusted + state.non_labor_portion)));
    state.total_calc_payment_rate = Decimal::from(i64::from(state.total_labor_adj_rate));
}

